import {test} from 'node:test'
import assert from 'node:assert/strict'
import * as T from 'three'
import {readRig} from '../scripts/check-animation.js'
import {attachSpiderAnimation} from '../src/spider-model.js'

test('Real GLB skin animates at rest and walking, loops, freezes on pause and resets',async()=>{
  const {scene,animations}=await readRig()
  assert.equal(animations[0].name,'Spider_default.005')
  const player=new T.Group(),mixer=new T.AnimationMixer(scene),action=mixer.clipAction(animations[0])
  attachSpiderAnimation(player,mixer,action)
  player.userData.resetAnimation()
  const snapshot=()=>{
    scene.updateMatrixWorld(true)
    const result=[]
    scene.traverse(mesh=>{
      if(!mesh.isSkinnedMesh)return
      mesh.skeleton.update()
      // Actual deformed vertices, not just mixer time or track presence.
      for(let i=0;i<mesh.geometry.attributes.position.count;i+=100){
        result.push(...mesh.getVertexPosition(i,new T.Vector3()).toArray())
      }
    })
    return result
  }
  const differs=(a,b)=>a.some((v,i)=>Math.abs(v-b[i])>1e-5)
  const first=snapshot()
  player.userData.updateAnimation(.4,false)
  assert.ok(differs(first,snapshot()),'idle must visibly deform the skin')
  const idleTime=action.time
  player.userData.updateAnimation(.4,true)
  assert.ok(action.time-idleTime>.4,'walking must play faster')
  assert.ok(differs(first,snapshot()),'walking must deform the skin')
  player.userData.resetAnimation()
  const resting=snapshot()
  player.userData.updateAnimation(.4,false,false,{turn:2.1})
  assert.ok(action.timeScale>1,'turning in place must step faster than idle')
  assert.ok(differs(resting,snapshot()),'turning must deform actual GLB vertices')
  const frozen=snapshot(),time=action.time
  player.userData.updateAnimation(1,true,true,{turn:-6})
  assert.equal(action.time,time);assert.deepEqual(snapshot(),frozen)
  for(let i=0;i<100;i++)player.userData.updateAnimation(.04,true)
  assert.ok(action.isRunning());assert.ok(action.time<action.getClip().duration)
  player.userData.resetAnimation()
  assert.equal(action.time,0);assert.deepEqual(snapshot(),first)
})

test('Turn and strafe blend smoothly in both directions without rotating the surface frame',()=>{
  const rig=new T.Group(),player=new T.Group(),visual=new T.Group()
  player.add(visual);visual.add(rig)
  const clip=new T.AnimationClip('gait',2,[new T.NumberKeyframeTrack('.position[y]',[0,1,2],[0,.1,0])])
  const mixer=new T.AnimationMixer(rig),action=mixer.clipAction(clip)
  attachSpiderAnimation(player,mixer,action,visual)
  player.userData.resetAnimation()
  player.userData.updateAnimation(.016,false,false,{turn:3})
  assert.ok(action.timeScale>.35&&action.timeScale<1.45,'pace blends, rather than snaps')
  assert.ok(visual.rotation.z<0)
  const tilt=visual.rotation.z,time=action.time,pace=action.timeScale
  player.userData.updateAnimation(1,true,true,{turn:-3,strafe:-1})
  assert.equal(visual.rotation.z,tilt);assert.equal(action.time,time);assert.equal(action.timeScale,pace)
  for(let i=0;i<50;i++)player.userData.updateAnimation(.016,false,false,{turn:-3})
  assert.ok(visual.rotation.z>0,'opposite turn reverses the lean')
  assert.ok(Math.abs(visual.rotation.z)<=.09)
  assert.deepEqual(player.quaternion.toArray(),[0,0,0,1])
  for(let i=0;i<100;i++)player.userData.updateAnimation(.016,false)
  assert.ok(Math.abs(visual.rotation.z)<1e-5)
  assert.ok(Math.abs(action.timeScale-.35)<1e-5,'stopping settles to idle')
  player.userData.updateAnimation(.4,true,false,{speed:1,strafe:1})
  assert.ok(visual.rotation.z<0,'strafing also shifts weight')
  player.userData.resetAnimation()
  assert.equal(visual.rotation.z,0);assert.equal(action.timeScale,.35);assert.equal(action.time,0)
})

